<?php declare(strict_types=1); namespace App\People\Application\Command\EndRelationship; use App\People\Domain\Repository\RelationshipRepository; use App\People\Domain\ValueObject\RelationshipId; #[\Symfony\Component\Messenger\Attribute\AsMessageHandler]
final readonly class EndRelationshipHandler {public function __construct(private RelationshipRepository $relationships){} public function __invoke(EndRelationshipCommand $c):void{$r=$this->relationships->findById(RelationshipId::fromString($c->relationshipId));if(!$r)throw new \RuntimeException('Relationship not found.');$r->end(new \DateTimeImmutable($c->endedAt));$this->relationships->save($r);}}
